// The home-screen widgets' native texts and looks (docs/widgets-spec.md; generated by scripts/brand/widget-native.mjs):
// both apps carry the same words in all 13 languages, none with a dash, and the old Style setting is gone.
import { test } from 'node:test'
import assert from 'node:assert/strict'
import fs from 'node:fs'

const root = new URL('../', import.meta.url)
const read = p => fs.readFileSync(new URL(p, root), 'utf8')
const LANGS = ['en', 'de', 'fr', 'es', 'it', 'nl', 'pl', 'cs', 'sl', 'pt', 'ja', 'zh', 'ko']
const JAVA = read('mobile/android/app/src/main/java/app/metablend/widget/WidgetText.java')
const SWIFT = read('mobile/ios/App/MetaBlendWidgets/WidgetLook.swift')
const strings = s => [...s.matchAll(/"((?:[^"\\]|\\.)*)"/g)].map(m => JSON.parse(`"${m[1]}"`))

// lang → [home, openOnce, pickCity, planHike, offline], the four messages and "Home city" both apps show
const rows = (src, re) => Object.fromEntries([...src.matchAll(re)].map(m => [m[1], strings(m[2])]))
const java = rows(JAVA, /T\.put\("(\w+)", new String\[\] \{ (.*) \}\);/g)
const swift = rows(SWIFT, /^\s+"(\w+)": \[(.*)\],$/gm)

test('widget texts: all 13 languages in both apps, the same words', () => {
  assert.deepEqual(Object.keys(java).sort(), [...LANGS].sort())
  assert.deepEqual(Object.keys(swift).sort(), [...LANGS].sort())
  for (const lang of LANGS) {
    const j = java[lang] // settings, city, home, show, hours, days, save, openOnce, pickCity, planHike, offline
    assert.equal(j.length, 11, lang)
    assert.deepEqual(swift[lang], [j[2], ...j.slice(7)], lang)
    for (const text of j) assert.ok(text.trim(), `${lang}: an empty text`)
  }
  // Japanese, Chinese and Korean are their own, never the English row
  for (const lang of ['ja', 'zh', 'ko']) for (let i = 0; i < 11; i++) assert.notEqual(java[lang][i], java.en[i], `${lang}[${i}]`)
})

test('widget texts: no dashes, and the offline message is two sentences', () => {
  for (const lang of LANGS) {
    for (const text of java[lang]) assert.doesNotMatch(text, /[–—]/, `${lang}: ${text}`)
    assert.doesNotMatch(java[lang][10], / - /, lang)
  }
  assert.equal(java.en[10], 'No connection. Tap to open MetaBlend.')
  assert.equal(java.de[10], 'Keine Verbindung. Tippen, um MetaBlend zu öffnen.')
})

test('widget settings: the Style option (Living sky, System) is gone on both platforms', () => {
  const settings = read('mobile/android/app/src/main/java/app/metablend/widget/WidgetConfigActivity.java')
  assert.doesNotMatch(settings, /"style"|tx\.get\("sky"\)|tx\.get\("system"\)/)
  assert.doesNotMatch(JAVA, /"style"|"Living sky"/)
  const intents = read('mobile/ios/App/MetaBlendWidgets/AppIntent.swift')
  assert.doesNotMatch(intents, /WidgetStyle|"Style"/)
  const catalog = JSON.parse(read('mobile/ios/App/MetaBlendWidgets/Localizable.xcstrings')).strings
  for (const k of ['Style', 'Living sky', 'System']) assert.ok(!(k in catalog), k)
  assert.doesNotMatch(read('mobile/ios/App/MetaBlendWidgets/MetaBlendWidgets.swift'), /SkyBackground|palette\(sky:|WidgetStyle/)
})

test('widget themes: Default, Mono, Winter and Sky with every colour role, light and dark', () => {
  const ROLES = ['ink', 'muted', 'window', 'rain', 'sun', 'moon', 'cloud']
  for (const dir of ['values', 'values-night']) {
    const xml = read(`mobile/android/app/src/main/res/${dir}/widget_colors.xml`)
    for (const t of ['default', 'mono', 'winter', 'sky']) for (const r of ROLES) assert.match(xml, new RegExp(`name="w_${t}_${r}">#[0-9a-f]{6}<`), `${dir} ${t} ${r}`)
  }
  // gold only on the sun, green only on a window (spec section 2): no role but sun is gold, none but window green
  const light = read('mobile/android/app/src/main/res/values/widget_colors.xml')
  assert.match(light, /w_default_sun">#966400</)
  assert.match(light, /w_default_window">#117948</)
  assert.equal((SWIFT.match(/case \(\.(standard|mono|winter|sky), (true|false)\): return Palette/g) ?? []).length, 8)
})
